"""Guarded atomic generated files and the single receipt publication lock."""

from __future__ import annotations

import fcntl
import hashlib
import os
import tempfile
from collections.abc import Iterator, Mapping
from contextlib import contextmanager, nullcontext
from dataclasses import dataclass
from pathlib import Path

from django.core.exceptions import ImproperlyConfigured

from django_compose.serving import Receipt, read_receipt


@contextmanager
def receipt_lock(output_dir: Path | str, *, write: bool = True) -> Iterator[None]:
    """Serialize mutations; a check never creates a directory or lock file."""
    root = Path(output_dir)
    GeneratedTree.validate_artifacts(root, {})
    if not write:
        path = root / ".compose.lock"
        if path.is_symlink():
            raise ValueError("Generated lock is a symlink")
        if path.exists():
            with path.open("rb") as stream:
                fcntl.flock(stream, fcntl.LOCK_SH)
                try:
                    yield
                finally:
                    fcntl.flock(stream, fcntl.LOCK_UN)
        else:
            yield
        return
    root.mkdir(parents=True, exist_ok=True)
    path = root / ".compose.lock"
    if path.is_symlink():
        raise ValueError("Generated lock is a symlink")
    with path.open("a+b") as stream:
        fcntl.flock(stream, fcntl.LOCK_EX)
        try:
            yield
        finally:
            fcntl.flock(stream, fcntl.LOCK_UN)


def atomic_write(path: Path, content: bytes) -> None:
    # Native loaders may otherwise accept same-second, same-size stale bytecode.
    caches: tuple[Path, ...] = ()
    if path.suffix == ".py" and "migrations" not in path.parts:
        cache_dir = path.parent / "__pycache__"
        if cache_dir.is_symlink():
            raise ValueError(f"Generated bytecode directory is a symlink: {cache_dir}")
        caches = tuple(sorted(cache_dir.glob(f"{path.stem}.*.pyc")))
        if any(cache.is_symlink() or not cache.is_file() for cache in caches):
            raise ValueError(f"Unsafe generated bytecode cache for {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary = tempfile.mkstemp(prefix=".compose-", dir=path.parent)
    try:
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        for cache in caches:
            cache.unlink(missing_ok=True)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


@dataclass
class GeneratedTree:
    """Only receipt-indexed outputs may be replaced; native history survives."""

    root: Path
    artifacts: Mapping[Path, bytes | str]

    @staticmethod
    def validate_artifacts(root: Path, artifacts: Mapping[Path, bytes | str]) -> None:
        if any(parent.is_symlink() for parent in (root, *root.parents)):
            raise ValueError(f"Generated root traverses a symlink: {root}")
        if root.exists() and not root.is_dir():
            raise ValueError(f"Generated root is not a directory: {root}")
        paths = set(artifacts)
        for relative, source in artifacts.items():
            if (
                not isinstance(relative, Path)
                or relative.is_absolute()
                or not relative.parts
                or ".." in relative.parts
            ):
                raise ValueError(f"Generated artifacts require a root-relative path: {relative!r}")
            if not isinstance(source, (str, bytes)):
                raise ValueError(f"Generated artifact must be bytes or text: {relative}")
            for part in (*relative.parents, relative):
                target = root / part
                if target.is_symlink() or (part != relative and target.exists() and not target.is_dir()):
                    raise ValueError(f"Unsafe generated path: {relative}")
            if (root / relative).is_dir() or any(parent in paths for parent in relative.parents):
                raise ValueError(f"Competing file/directory artifact: {relative}")

    def _validate(self) -> Receipt | None:
        self.validate_artifacts(self.root, self.artifacts)
        receipt = read_receipt(self.root)
        if (
            receipt is None
            and self.root.exists()
            and any(path.name != ".compose.lock" for path in self.root.iterdir())
        ):
            raise ValueError(f"{self.root} lacks the required generated-output marker")
        owned = receipt.OWNED_FILES if receipt else {}
        self.validate_artifacts(self.root, {Path(path): b"" for path in owned})
        for relative, source in self.artifacts.items():
            target = self.root / relative
            if (
                "migrations" in relative.parts
                and target.exists()
                and target.read_bytes() != self._bytes(source)
            ):
                raise ValueError(f"Cannot overwrite native migration history: {relative}")
            if (
                target.exists()
                and relative.as_posix() not in owned
                and relative != Path("__init__.py")
                and "migrations" not in relative.parts
            ):
                raise ValueError(f"Generated artifact collides with an unowned file: {relative}")
        return receipt

    @staticmethod
    def _bytes(value: bytes | str) -> bytes:
        return value.encode() if isinstance(value, str) else value

    def drift(self) -> list[Path]:
        previous = self._validate()
        changed = {
            p
            for p, value in self.artifacts.items()
            if not (self.root / p).is_file() or (self.root / p).read_bytes() != self._bytes(value)
        }
        old = {Path(p) for p in previous.OWNED_FILES} if previous else set()
        return sorted(
            changed
            | {
                p
                for p in old - set(self.artifacts)
                if "migrations" not in p.parts and (self.root / p).exists()
            }
        )

    def reconcile(self, *, prune: bool = True) -> bool:
        previous = self._validate()
        changed = False
        for relative, value in sorted(self.artifacts.items()):
            target = self.root / relative
            content = self._bytes(value)
            if not target.is_file() or target.read_bytes() != content:
                atomic_write(target, content)
                changed = True
        if prune and previous:
            for name in sorted(set(previous.OWNED_FILES) - {p.as_posix() for p in self.artifacts}):
                relative = Path(name)
                if "migrations" not in relative.parts and (self.root / relative).is_file():
                    (self.root / relative).unlink()
                    changed = True
        return changed

    def hashes(self) -> dict[str, str]:
        return {
            p.as_posix(): hashlib.sha256(self._bytes(value)).hexdigest()
            for p, value in sorted(self.artifacts.items())
            if p != Path("__init__.py") and "migrations" not in p.parts
        }

    def clean(self) -> tuple[Path, ...]:
        with receipt_lock(self.root):
            receipt = self._validate()
            if receipt is None:
                return ()
            invalid = Receipt(
                receipt.GENERATION,
                receipt.HISTORY_LABELS,
                receipt.RETIRED_LABELS,
                receipt.DIGEST,
                receipt.OWNED_FILES,
                receipt.COMPILER,
                receipt.MODEL_LABELS,
                True,
            )
            atomic_write(self.root / "__init__.py", invalid.source().encode())
            for name in sorted(receipt.OWNED_FILES):
                path = Path(name)
                if "migrations" not in path.parts and (self.root / path).is_file():
                    (self.root / path).unlink()
            return tuple(sorted(path.relative_to(self.root) for path in self.root.rglob("*")))


def update_receipt(
    output_dir: Path | str, *, retired_labels: tuple[str, ...], locked: bool = False
) -> Receipt:
    """Publish retirement under the same invalidate-first writer protocol."""
    root = Path(output_dir)
    with nullcontext() if locked else receipt_lock(root):
        previous = read_receipt(root)
        if previous is None or previous.IN_PROGRESS:
            raise ImproperlyConfigured("History retirement requires a complete receipt; run compose")
        GeneratedTree(root, {}).validate_artifacts(root, {Path(p): b"" for p in previous.OWNED_FILES})
        invalid = Receipt(
            previous.GENERATION,
            previous.HISTORY_LABELS,
            previous.RETIRED_LABELS,
            previous.DIGEST,
            previous.OWNED_FILES,
            previous.COMPILER,
            previous.MODEL_LABELS,
            True,
        )
        atomic_write(root / "__init__.py", invalid.source().encode())
        retired = tuple(sorted(set(previous.RETIRED_LABELS) | set(retired_labels)))
        result = Receipt(
            previous.GENERATION,
            tuple(label for label in previous.HISTORY_LABELS if label not in retired),
            retired,
            previous.DIGEST,
            previous.OWNED_FILES,
            previous.COMPILER,
            previous.MODEL_LABELS,
        )
        atomic_write(root / "__init__.py", result.source().encode())
        return result
